r=json.loads(Path(sys.argv[1]).read_text());p=Path(r["source_path"]).read_bytes()
assert hashlib.sha256(p).hexdigest()==r["source_sha256"]
a=p.split(b"\n");out=[];before={x for x,y in r["note_line_ranges"]};after={y for x,y in r["note_line_ranges"]}
for lo,hi in r["physical_line_ranges"]:
 part=[]
 for i in range(lo,hi+1):
  if i in r["remove_blank_lf_lines"]:
   assert not a[i-1].strip();continue
  if i in before:part.append(b"")
  part.append(a[i-1])
  if i in after:part.append(b"")
 out.append(b"\n".join(part))
b=b"\n\n".join(out)+b"\n"
base=b"".join(b"".join(a[lo-1:hi]) for lo,hi in r["physical_line_ranges"])
assert base.replace(b"\n",b"")==b.replace(b"\n",b"")
assert hashlib.sha256(b).hexdigest()==r["expected_sha256"]
Path(sys.argv[2]).write_bytes(b)

